import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Send, Upload, Settings, Play, Square, BarChart3, FileText, Zap, TrendingUp, Clock, CheckCircle, XCircle, Activity, Database, Shield, Globe } from 'lucide-react';
import './App.css';

const API_URL = 'http://localhost:8000/api';

function App() {
  const [status, setStatus] = useState('idle');
  const [config, setConfig] = useState(null);
  const [logs, setLogs] = useState([]);
  const [statistics, setStatistics] = useState(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [uploadedFile, setUploadedFile] = useState(null);
  const [isDragging, setIsDragging] = useState(false);

  useEffect(() => {
    fetchStatus();
    fetchConfig();
    const interval = setInterval(fetchStatus, 2000);
    return () => clearInterval(interval);
  }, []);

  const fetchStatus = async () => {
    try {
      const response = await axios.get(`${API_URL}/status`);
      setStatus(response.data.status);
      setLogs(response.data.logs || []);
    } catch (error) {
      console.error('Erro ao buscar status:', error);
    }
  };

  const fetchConfig = async () => {
    try {
      const response = await axios.get(`${API_URL}/config`);
      setConfig(response.data);
    } catch (error) {
      console.error('Erro ao buscar config:', error);
    }
  };

  const startCampaign = async () => {
    try {
      await axios.post(`${API_URL}/start-campaign`, config);
      fetchStatus();
    } catch (error) {
      console.error('Erro ao iniciar campanha:', error);
    }
  };

  const stopCampaign = async () => {
    try {
      await axios.post(`${API_URL}/stop-campaign`);
      fetchStatus();
    } catch (error) {
      console.error('Erro ao parar campanha:', error);
    }
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post(`${API_URL}/upload-csv`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      setUploadedFile(response.data);

      const newConfig = { ...config, arquivo_leads: response.data.filepath };
      await axios.post(`${API_URL}/config`, newConfig);
      setConfig(newConfig);

    } catch (error) {
      console.error('Erro ao fazer upload:', error);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = async (e) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (!file || !file.name.endsWith('.csv')) {
      alert('Por favor, selecione um arquivo CSV');
      return;
    }

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post(`${API_URL}/upload-csv`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      setUploadedFile(response.data);

      const newConfig = { ...config, arquivo_leads: response.data.filepath };
      await axios.post(`${API_URL}/config`, newConfig);
      setConfig(newConfig);

    } catch (error) {
      console.error('Erro ao fazer upload:', error);
    }
  };

  const updateConfig = async (key, value) => {
    const newConfig = { ...config, [key]: value };
    setConfig(newConfig);
    await axios.post(`${API_URL}/config`, newConfig);
  };

  const getStatusColor = () => {
    switch (status) {
      case 'running': return 'from-green-500 to-emerald-600';
      case 'completed': return 'from-blue-500 to-indigo-600';
      case 'error': return 'from-red-500 to-rose-600';
      default: return 'from-gray-500 to-slate-600';
    }
  };

  const getStatusText = () => {
    switch (status) {
      case 'running': return 'Em Execução';
      case 'completed': return 'Concluído';
      case 'error': return 'Erro';
      case 'stopped': return 'Parado';
      default: return 'Aguardando';
    }
  };

  const getStatusIcon = () => {
    switch (status) {
      case 'running': return <Activity className="animate-pulse" />;
      case 'completed': return <CheckCircle />;
      case 'error': return <XCircle />;
      default: return <Clock />;
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <header className="mb-12 text-center">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-green-400 to-emerald-600 rounded-2xl mb-6 shadow-2xl shadow-green-500/30">
            <Send className="text-white" size={40} />
          </div>
          <h1 className="text-5xl font-bold bg-gradient-to-r from-white to-gray-300 bg-clip-text text-transparent mb-3">
            WhatsApp Automation
          </h1>
          <p className="text-gray-400 text-lg">Sistema avançado de automação de envio de mensagens</p>
        </header>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-10">
          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 shadow-xl hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${getStatusColor()} flex items-center justify-center`}>
                {getStatusIcon()}
              </div>
              <div className={`w-3 h-3 rounded-full ${status === 'running' ? 'bg-green-500 animate-pulse' : 'bg-gray-500'}`} />
            </div>
            <p className="text-gray-400 text-sm font-medium mb-1">Status</p>
            <p className="text-2xl font-bold text-white">{getStatusText()}</p>
          </div>

          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 shadow-xl hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-green-500 to-emerald-600 flex items-center justify-center">
                <CheckCircle className="text-white" />
              </div>
              <Zap className="text-green-400" />
            </div>
            <p className="text-gray-400 text-sm font-medium mb-1">Enviados</p>
            <p className="text-2xl font-bold text-white">{statistics?.campaign_state?.sent || 0}</p>
          </div>

          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 shadow-xl hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-red-500 to-rose-600 flex items-center justify-center">
                <XCircle className="text-white" />
              </div>
              <TrendingUp className="text-red-400" />
            </div>
            <p className="text-gray-400 text-sm font-medium mb-1">Falhas</p>
            <p className="text-2xl font-bold text-white">{statistics?.campaign_state?.failed || 0}</p>
          </div>

          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 shadow-xl hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center">
                <BarChart3 className="text-white" />
              </div>
              <Activity className="text-blue-400" />
            </div>
            <p className="text-gray-400 text-sm font-medium mb-1">Progresso</p>
            <p className="text-2xl font-bold text-white">{statistics?.campaign_state?.progress || 0}%</p>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="flex gap-3 mb-8 bg-white/5 backdrop-blur-lg p-2 rounded-2xl border border-white/10">
          {[
            { id: 'dashboard', icon: BarChart3, label: 'Dashboard' },
            { id: 'upload', icon: Upload, label: 'Upload CSV' },
            { id: 'config', icon: Settings, label: 'Configurações' },
            { id: 'logs', icon: FileText, label: 'Logs' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-1 flex items-center justify-center gap-2 px-6 py-4 rounded-xl font-semibold transition-all duration-300 ${
                activeTab === tab.id 
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 text-white shadow-lg shadow-green-500/30' 
                  : 'text-gray-400 hover:text-white hover:bg-white/10'
              }`}
            >
              <tab.icon size={20} />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Action Buttons */}
        <div className="flex gap-4 mb-10">
          {status !== 'running' ? (
            <button
              onClick={startCampaign}
              className="flex-1 bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 px-8 py-4 rounded-2xl font-bold text-lg shadow-xl shadow-green-500/30 hover:shadow-green-500/50 transition-all duration-300 flex items-center justify-center gap-3 hover:scale-105"
            >
              <Play size={24} />
              Iniciar Campanha
            </button>
          ) : (
            <button
              onClick={stopCampaign}
              className="flex-1 bg-gradient-to-r from-red-500 to-rose-600 hover:from-red-600 hover:to-rose-700 px-8 py-4 rounded-2xl font-bold text-lg shadow-xl shadow-red-500/30 hover:shadow-red-500/50 transition-all duration-300 flex items-center justify-center gap-3 hover:scale-105"
            >
              <Square size={24} />
              Parar Campanha
            </button>
          )}
        </div>

        {/* Content Panels */}
        {activeTab === 'dashboard' && (
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 border border-white/20 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
              <Database className="text-green-400" />
              Dashboard
            </h2>
            {uploadedFile ? (
              <div className="space-y-6">
                <div className="bg-white/5 rounded-2xl p-6 border border-white/10">
                  <h3 className="font-semibold mb-4 text-lg flex items-center gap-2">
                    <Globe className="text-blue-400" />
                    Arquivo Carregado
                  </h3>
                  <div className="grid grid-cols-3 gap-4">
                    <div className="bg-white/5 rounded-xl p-4">
                      <p className="text-gray-400 text-sm">Nome</p>
                      <p className="font-semibold">{uploadedFile.filename}</p>
                    </div>
                    <div className="bg-white/5 rounded-xl p-4">
                      <p className="text-gray-400 text-sm">Total de Leads</p>
                      <p className="font-semibold text-green-400">{uploadedFile.total_rows}</p>
                    </div>
                    <div className="bg-white/5 rounded-xl p-4">
                      <p className="text-gray-400 text-sm">Colunas</p>
                      <p className="font-semibold">{uploadedFile.columns.length}</p>
                    </div>
                  </div>
                </div>

                <div className="bg-white/5 rounded-2xl p-6 border border-white/10">
                  <h3 className="font-semibold mb-4 text-lg flex items-center gap-2">
                    <Shield className="text-purple-400" />
                    Prévia dos Dados
                  </h3>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-white/10">
                          {uploadedFile.columns.map(col => (
                            <th key={col} className="text-left p-3 font-semibold text-gray-300">{col}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {uploadedFile.preview.map((row, idx) => (
                          <tr key={idx} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                            {uploadedFile.columns.map(col => (
                              <td key={col} className="p-3 text-gray-300">{String(row[col]).substring(0, 50)}</td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ) : (
              <div className="text-center py-12">
                <Upload className="mx-auto mb-4 text-gray-500" size={64} />
                <p className="text-gray-400 text-lg">Nenhum arquivo carregado</p>
                <p className="text-gray-500">Vá para a aba "Upload CSV" para começar</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'upload' && (
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 border border-white/20 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
              <Upload className="text-green-400" />
              Upload CSV
            </h2>
            <div
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-3xl p-12 text-center transition-all duration-300 ${
                isDragging 
                  ? 'border-green-500 bg-green-500/10 scale-105' 
                  : 'border-white/20 hover:border-green-500/50 hover:bg-white/5'
              }`}
            >
              <Upload className={`mx-auto mb-6 ${isDragging ? 'text-green-400' : 'text-gray-500'}`} size={80} />
              <p className="text-gray-300 text-lg mb-4">
                {isDragging ? 'Solte o arquivo aqui' : 'Arraste seu arquivo CSV aqui ou clique para selecionar'}
              </p>
              <input
                type="file"
                accept=".csv"
                onChange={handleFileUpload}
                className="hidden"
                id="file-upload"
              />
              <label
                htmlFor="file-upload"
                className="inline-block bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 px-8 py-4 rounded-xl cursor-pointer font-semibold transition-all duration-300 hover:scale-105 shadow-lg shadow-green-500/30"
              >
                Selecionar Arquivo
              </label>
            </div>
          </div>
        )}

        {activeTab === 'config' && config && (
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 border border-white/20 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
              <Settings className="text-green-400" />
              Configurações
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-white/5 rounded-2xl p-6 border border-white/10">
                <label className="block text-gray-400 mb-3 font-medium">Tamanho do Lote</label>
                <input
                  type="number"
                  value={config.lote_tamanho}
                  onChange={(e) => updateConfig('lote_tamanho', parseInt(e.target.value))}
                  className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-white focus:outline-none focus:border-green-500 transition-colors"
                />
              </div>
              <div className="bg-white/5 rounded-2xl p-6 border border-white/10">
                <label className="block text-gray-400 mb-3 font-medium">Tempo Mínimo (s)</label>
                <input
                  type="number"
                  value={config.tempo_entre_msg_min}
                  onChange={(e) => updateConfig('tempo_entre_msg_min', parseInt(e.target.value))}
                  className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-white focus:outline-none focus:border-green-500 transition-colors"
                />
              </div>
              <div className="bg-white/5 rounded-2xl p-6 border border-white/10">
                <label className="block text-gray-400 mb-3 font-medium">Tempo Máximo (s)</label>
                <input
                  type="number"
                  value={config.tempo_entre_msg_max}
                  onChange={(e) => updateConfig('tempo_entre_msg_max', parseInt(e.target.value))}
                  className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-white focus:outline-none focus:border-green-500 transition-colors"
                />
              </div>
              <div className="bg-white/5 rounded-2xl p-6 border border-white/10">
                <label className="block text-gray-400 mb-3 font-medium">DDI Padrão</label>
                <input
                  type="text"
                  value={config.ddi_padrao}
                  onChange={(e) => updateConfig('ddi_padrao', e.target.value)}
                  className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-white focus:outline-none focus:border-green-500 transition-colors"
                />
              </div>
              <div className="md:col-span-2 bg-white/5 rounded-2xl p-6 border border-white/10">
                <label className="flex items-center gap-4 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={config.modo_teste}
                    onChange={(e) => updateConfig('modo_teste', e.target.checked)}
                    className="w-6 h-6 accent-green-500"
                  />
                  <span className="text-gray-300 font-medium">Modo Teste (não envia mensagens reais)</span>
                </label>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'logs' && (
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 border border-white/20 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
              <FileText className="text-green-400" />
              Logs da Campanha
            </h2>
            <div className="bg-black/30 rounded-2xl p-6 h-96 overflow-y-auto font-mono text-sm border border-white/10">
              {logs.length === 0 ? (
                <div className="text-center py-12">
                  <FileText className="mx-auto mb-4 text-gray-500" size={48} />
                  <p className="text-gray-400">Nenhum log disponível</p>
                </div>
              ) : (
                logs.map((log, idx) => (
                  <div key={idx} className="mb-3 text-gray-300">
                    <span className="text-green-400">{log.timestamp}</span>
                    <span className="ml-3">{log.message}</span>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
